// fs-auto-continue: submit this working page once, shortly after it renders.
(function () {
  setTimeout(function () {
    var b = document.querySelector('[data-skbuttonvalue="CONTINUE"]');
    if (!b || b.getAttribute('data-fs-sent')) { return; }
    b.setAttribute('data-fs-sent', '1');
    b.click();
  }, 300);
})();

